import{I as n,o as t,c as o,b6 as i,J as p,w as u,j as s,a}from"./chunks/framework.BUXTSoD9.js";const b=JSON.parse(`{"title":"Le modèle Double Diamond : faire d'abord les bonnes choses, puis faire les choses correctement","description":"Article d'introduction au Double Diamond pour les lecteurs débutants. Comprendre les quatre phases Discover, Define, Develop, Deliver, et éviter de se précipiter dans les prototypes avant d'avoir compris le problème.","frontmatter":{"title":"Le modèle Double Diamond : faire d'abord les bonnes choses, puis faire les choses correctement","description":"Article d'introduction au Double Diamond pour les lecteurs débutants. Comprendre les quatre phases Discover, Define, Develop, Deliver, et éviter de se précipiter dans les prototypes avant d'avoir compris le problème."},"headers":[],"relativePath":"fr-fr/stage-1/appendix-double-diamond/index.md","filePath":"fr-fr/stage-1/appendix-double-diamond/index.md"}`),d={name:"fr-fr/stage-1/appendix-double-diamond/index.md"},v=Object.assign(d,{setup(c){const r="Environ <strong>1,5 heure</strong>";return(m,e)=>{const l=n("ChapterIntroduction");return t(),o("div",null,[e[1]||(e[1]=i('<h1 id="le-modele-double-diamond-faire-d-abord-les-bonnes-choses-puis-faire-les-choses-correctement" tabindex="-1">Le modèle Double Diamond : faire d&#39;abord les bonnes choses, puis faire les choses correctement <a class="header-anchor" href="#le-modele-double-diamond-faire-d-abord-les-bonnes-choses-puis-faire-les-choses-correctement" aria-label="Permalink to “Le modèle Double Diamond : faire d&#39;abord les bonnes choses, puis faire les choses correctement”">​</a></h1><p><a id="top-dd"></a></p><h2 id="introduction-du-chapitre" tabindex="-1">Introduction du chapitre <a class="header-anchor" href="#introduction-du-chapitre" aria-label="Permalink to “Introduction du chapitre”">​</a></h2>',3)),p(l,{duration:r,tags:["Double Diamond","Design Thinking","Analyse des besoins","Conception de solutions"],coreOutput:"1 définition de problème plus claire et 1 point d'entrée de validation plus raisonnable",expectedOutput:"Ne plus se précipiter pour dessiner des prototypes, mais savoir d'abord clarifier le problème avant de comparer les solutions"},{default:u(()=>[...e[0]||(e[0]=[s("p",null,"Beaucoup de gens, lorsqu'ils créent un produit pour la première fois, le piège le plus courant n'est pas « ne pas travailler assez dur », mais de passer trop vite à la solution.",-1),s("p",null,"À peine une direction a-t-elle germé dans leur esprit qu'ils commencent à penser : comment dessiner les pages, où placer les boutons, faut-il intégrer l'IA, faut-il faire un système de connexion, quel outil utiliser pour les prototypes. Après s'être agité un moment, ils se rendent compte que le problème fondamental n'a jamais été vraiment clarifié : les utilisateurs ont-ils vraiment ce point de douleur ? Ce problème mérite-t-il d'être résolu maintenant ? Vous pensiez faire avancer le projet, mais en réalité vous accélérez juste dans la mauvaise direction.",-1),s("p",null,"Le modèle Double Diamond est conçu pour éviter ce genre de situation.",-1),s("p",null,[a("Son rappel le plus précieux est : "),s("strong",null,"« faire les bonnes choses » et « faire les choses correctement » sont deux étapes complètement différentes."),a(" Si vous n'avez pas encore compris le problème et que vous vous précipitez pour faire un prototype, vous ne ferez généralement que rendre la mauvaise direction plus complète.")],-1)])]),_:1}),e[2]||(e[2]=i(`<div class="info custom-block"><p class="custom-block-title">SOP minimale</p><p><strong>Objectif</strong> : après avoir lu, vous saurez mieux quand réfléchir d&#39;abord au problème et quand commencer à penser aux solutions et aux prototypes, évitant ainsi de travailler dur dans la mauvaise direction dès le début.</p><p><strong>Actions</strong> : suivez les quatre étapes <code>Discover → Define → Develop → Deliver</code>, en ne faisant à chaque étape que ce qui est nécessaire.</p><p><strong>Résultat</strong> : vous obtiendrez une définition de problème plus claire, plusieurs solutions comparables, et une version minimale validable.</p><p><strong>Navigation rapide</strong> : <a href="#dd-what">Qu&#39;est-ce que le Double Diamond</a> · <a href="#dd-first">Le premier diamant</a> · <a href="#dd-ai">Comment l&#39;IA peut vous aider</a></p></div><h2 id="ce-que-vous-apprendrez" tabindex="-1">Ce que vous apprendrez <a class="header-anchor" href="#ce-que-vous-apprendrez" aria-label="Permalink to “Ce que vous apprendrez”">​</a></h2><ol><li>Qu&#39;est-ce que le modèle Double Diamond, et pourquoi il est adapté aux débutants en création de produit</li><li>Ce que font les quatre phases Discover, Define, Develop, Deliver</li><li>Comment distinguer « je devrais continuer à diverger » de « je devrais commencer à converger »</li><li>Comment appliquer le modèle Double Diamond aux produits AI, à la conception de prototypes et à la validation des besoins</li></ol><p><a id="dd-what"></a></p><h2 id="_1-qu-est-ce-que-le-modele-double-diamond" tabindex="-1"><a href="#top-dd">1. Qu&#39;est-ce que le modèle Double Diamond</a> <a class="header-anchor" href="#_1-qu-est-ce-que-le-modele-double-diamond" aria-label="Permalink to “1. Qu&#39;est-ce que le modèle Double Diamond”">​</a></h2><p>Le modèle Double Diamond est un cadre de processus de design classique promu par le <strong>Design Council</strong> britannique. Il représente un processus complet de design et d&#39;innovation sous la forme de deux diamants consécutifs.</p><p>La raison pour laquelle c&#39;est des « diamants » est que chaque diamant comprend deux actions opposées mais toutes deux importantes :</p><ul><li><strong>Divergence</strong> : élargir d&#39;abord la vision, voir plus de possibilités</li><li><strong>Convergence</strong> : réduire ensuite le périmètre, prendre des décisions et faire des compromis</li></ul><p>Le processus complet se déroule en quatre étapes :</p><ol><li><strong>Discover</strong> : comprendre largement les utilisateurs, les problèmes, l&#39;environnement et le marché</li><li><strong>Define</strong> : extraire des masses d&#39;informations le problème central véritablement digne d&#39;être résolu</li><li><strong>Develop</strong> : diverger autour du problème central pour trouver plusieurs solutions</li><li><strong>Deliver</strong> : filtrer, prototyper, tester et livrer la solution la plus appropriée</li></ol><p>Si l&#39;on compresse ces quatre étapes en une seule phrase facile à retenir :</p><ul><li><strong>Le premier diamant</strong> : comprendre d&#39;abord quel problème résoudre exactement</li><li><strong>Le deuxième diamant</strong> : décider ensuite quelle solution utiliser pour le résoudre</li></ul><p>C&#39;est aussi la phrase que vous avez prononcée avec justesse :</p><ul><li><strong>Le premier diamant : faire les bonnes choses</strong></li><li><strong>Le deuxième diamant : faire les choses correctement</strong></li></ul><h2 id="_2-pourquoi-le-modele-double-diamond-est-particulierement-adapte-aux-debutants" tabindex="-1">2. Pourquoi le modèle Double Diamond est particulièrement adapté aux débutants <a class="header-anchor" href="#_2-pourquoi-le-modele-double-diamond-est-particulierement-adapte-aux-debutants" aria-label="Permalink to “2. Pourquoi le modèle Double Diamond est particulièrement adapté aux débutants”">​</a></h2><p>Le rythme le plus courant chez les débutants en création de produit ressemble souvent à ça :</p><ul><li>Avoir une idée</li><li>Trouver la direction cool</li><li>Commencer immédiatement à dessiner des prototypes</li><li>En construisant, découvrir que les fonctionnalités se multiplient</li><li>Finalement, ne plus savoir quel problème on résout</li></ul><p>La valeur du modèle Double Diamond n&#39;est pas de rendre le processus plus complexe, mais de <strong>vous forcer à séparer « comprendre le problème » et « concevoir la solution »</strong>.</p><p>Cela semble banal, mais c&#39;est en réalité très important. Parce que beaucoup de produits qui échouent ne le font pas par manque d&#39;effort, mais parce que :</p><ul><li>Ils ont choisi le mauvais problème</li><li>Ils ont mal compris les utilisateurs</li><li>Ils ont verrouillé une solution trop tôt</li><li>Ils ont passé beaucoup de temps à peaufiner les détails sans valider la direction</li></ul><p>Le modèle Double Diamond vous rappelle constamment :</p><ul><li>Ne présumez pas que le problème est établi juste parce que l&#39;idée semble bonne</li><li>Ne présumez pas que la solution mérite d&#39;être réalisée juste parce qu&#39;elle est réalisable</li><li>Ne présumez pas que les utilisateurs en auront vraiment besoin juste parce que le prototype paraît complet</li></ul><p><a id="dd-first"></a></p><h2 id="_3-le-premier-diamant-faire-les-bonnes-choses" tabindex="-1"><a href="#top-dd">3. Le premier diamant : faire les bonnes choses</a> <a class="header-anchor" href="#_3-le-premier-diamant-faire-les-bonnes-choses" aria-label="Permalink to “3. Le premier diamant : faire les bonnes choses”">​</a></h2><p>Le premier diamant se concentre sur <strong>le problème lui-même</strong>, pas sur la solution.</p><p>Vous pouvez le résumer en une phrase : <strong>ne vous précipitez pas, déterminez d&#39;abord si ça vaut la peine d&#39;être fait.</strong></p><h3 id="_3-1-discover-ouvrir-d-abord-l-espace-du-probleme" tabindex="-1">3.1 Discover : ouvrir d&#39;abord l&#39;espace du problème <a class="header-anchor" href="#_3-1-discover-ouvrir-d-abord-l-espace-du-probleme" aria-label="Permalink to “3.1 Discover : ouvrir d&#39;abord l&#39;espace du problème”">​</a></h3><p>La tâche centrale de la phase Discover est de <strong>faire une recherche large, pas de tirer des conclusions rapides</strong>.</p><p>Les activités typiques de cette étape incluent :</p><ul><li>Observer comment les utilisateurs se comportent dans des scénarios réels</li><li>Interviewer des utilisateurs potentiels pour comprendre quand ils ont rencontré le problème pour la dernière fois</li><li>Observer comment ils se débrouillent actuellement</li><li>Examiner comment les concurrents et les alternatives gèrent la situation</li><li>Collecter des informations sur le marché, les processus, les contraintes, la chaîne de valeur</li></ul><p>Beaucoup de gens pensent à tort que Discover consiste à « lire plus de documentation ». En réalité, ce qui est plus crucial, c&#39;est : <strong>vous devez comprendre les personnes et les contextes, pas juste accumuler des informations.</strong></p><p>Par exemple, si vous voulez créer un outil « AI qui aide à organiser les comptes rendus de réunion », en phase Discover, il serait plus pertinent de se concentrer sur :</p><ul><li>Où les utilisateurs souffrent-ils le plus après une réunion</li><li>Est-ce la prise de notes, l&#39;organisation, ou la synchronisation qui est difficile</li><li>Est-ce qu&#39;ils écrivent eux-mêmes, demandent à des stagiaires, réécoutent les enregistrements, ou ne font simplement pas de compte rendu</li><li>Quels types de réunions nécessitent le plus un compte rendu, lesquels n&#39;en ont pas besoin du tout</li></ul><p>L&#39;objectif le plus important de cette étape n&#39;est pas d&#39;obtenir une réponse, mais de <strong>ne pas supposer trop tôt que vous connaissez déjà la réponse.</strong></p><h3 id="_3-2-define-extraire-le-probleme-central-de-la-masse-d-informations" tabindex="-1">3.2 Define : extraire le problème central de la masse d&#39;informations <a class="header-anchor" href="#_3-2-define-extraire-le-probleme-central-de-la-masse-d-informations" aria-label="Permalink to “3.2 Define : extraire le problème central de la masse d&#39;informations”">​</a></h3><p>Si Discover est l&#39;ouverture, Define est le recentrage.</p><p>La phase Define ne consiste pas à conserver toutes les observations, mais à se demander :</p><ul><li>Quel est le problème véritablement prioritaire à résoudre</li><li>Quel problème est le plus fréquent, le plus douloureux, le plus porteur de valeur</li><li>Quelle est la seule scène à cibler pour la première version</li></ul><p>L&#39;essence de cette étape est de transformer un sujet large en une définition de problème claire.</p><p>Par exemple, au début vous disiez :</p><blockquote><p>Je veux créer un outil AI pour améliorer l&#39;efficacité des réunions.</p></blockquote><p>En phase Define, une meilleure formulation pourrait devenir :</p><blockquote><p>Nous allons d&#39;abord résoudre le problème des équipes projet qui, après des réunions collaboratives de 30 à 60 minutes, ne parviennent pas à produire en 10 minutes un compte rendu incluant les tâches, les responsables et les délais.</p></blockquote><p>À ce stade, le problème commence à devenir clair :</p><ul><li>Qui est l&#39;utilisateur</li><li>Quel est le contexte</li><li>Quel est le blocage</li><li>Quel est le critère de succès</li></ul><p>L&#39;essence de Define est de <strong>passer de « beaucoup de problèmes » à « quel problème résoudre en premier cette fois-ci ».</strong></p><h2 id="_4-le-deuxieme-diamant-faire-les-choses-correctement" tabindex="-1">4. Le deuxième diamant : faire les choses correctement <a class="header-anchor" href="#_4-le-deuxieme-diamant-faire-les-choses-correctement" aria-label="Permalink to “4. Le deuxième diamant : faire les choses correctement”">​</a></h2><p>Ce n&#39;est qu&#39;après avoir terminé le premier diamant qu&#39;il est vraiment approprié d&#39;entrer dans le deuxième. Parce qu&#39;à ce stade, vous ne résolvez pas une direction vague, mais un problème spécifique qui a été cerné.</p><h3 id="_4-1-develop-diverger-les-solutions-autour-du-probleme-central" tabindex="-1">4.1 Develop : diverger les solutions autour du problème central <a class="header-anchor" href="#_4-1-develop-diverger-les-solutions-autour-du-probleme-central" aria-label="Permalink to “4.1 Develop : diverger les solutions autour du problème central”">​</a></h3><p>L&#39;accent de la phase Develop est de <strong>plorer plusieurs solutions possibles pour le même problème</strong>.</p><p>Notez que cette divergence est différente de celle de la phase Discover.</p><ul><li>La divergence de Discover explore l&#39;espace des problèmes</li><li>La divergence de Develop explore l&#39;espace des solutions</li></ul><p>Par exemple, pour le cas du compte rendu de réunion, en phase Develop, vous pouvez commencer à penser :</p><ul><li>Faire un outil web ou un plugin de réunion</li><li>Traiter après upload de l&#39;enregistrement ou faire une prise de notes en temps réel</li><li>Ne faire que des résumés ou se concentrer sur l&#39;extraction des tâches</li><li>Mettre l&#39;accent sur l&#39;efficacité individuelle ou la synchronisation d&#39;équipe</li><li>Donner aux utilisateurs la liberté d&#39;éditer ou produire directement un modèle structuré</li></ul><p>Cette étape se prête bien au brainstorming, et aussi à l&#39;élargissement des solutions avec l&#39;équipe.</p><p>Mais il y a un prérequis : <strong>toutes les solutions doivent servir le même problème déjà défini.</strong> Si le problème n&#39;est pas clairement défini, Develop risque de redevenir une dispersion de fonctionnalités.</p><h3 id="_4-2-deliver-choisir-la-solution-faire-le-prototype-tester-et-livrer" tabindex="-1">4.2 Deliver : choisir la solution, faire le prototype, tester et livrer <a class="header-anchor" href="#_4-2-deliver-choisir-la-solution-faire-le-prototype-tester-et-livrer" aria-label="Permalink to “4.2 Deliver : choisir la solution, faire le prototype, tester et livrer”">​</a></h3><p>La phase Deliver est l&#39;étape de convergence du deuxième diamant.</p><p>Ce qu&#39;il faut faire ici n&#39;est pas de continuer à imaginer plus, mais de commencer à juger :</p><ul><li>Quelle solution est la plus adaptée à la phase actuelle</li><li>Quelle version est la plus petite mais la plus utile</li><li>Quelles fonctionnalités sont essentielles d&#39;abord, lesquelles peuvent attendre</li><li>Comment prototyper, tester et valider à petite échelle</li></ul><p>Beaucoup de gens pensent que Deliver équivaut à « mise en ligne ». En réalité, son sens plus précis est : <strong>transformer une solution en quelque chose de testable, de validable et d&#39;itérable.</strong></p><p>Cela peut être :</p><ul><li>Un flux basse fidélité</li><li>Un prototype Figma</li><li>Un MVP fonctionnel</li><li>Un test utilisateur à petite échelle</li><li>Une version itérée après des retours réels</li></ul><p>L&#39;essentiel de Deliver n&#39;est pas la « livraison parfaite », mais de <strong>mettre la solution dans un environnement réel pour validation aussi rapidement que possible.</strong></p><h2 id="_5-un-tableau-comparatif-facile-a-retenir" tabindex="-1">5. Un tableau comparatif facile à retenir <a class="header-anchor" href="#_5-un-tableau-comparatif-facile-a-retenir" aria-label="Permalink to “5. Un tableau comparatif facile à retenir”">​</a></h2><p>Si vous n&#39;arrivez jamais à distinguer les quatre phases, retenez simplement cette version :</p><table tabindex="0"><thead><tr><th>Phase</th><th>Ce que vous faites</th><th>Mots-clés</th><th>Produits courants</th></tr></thead><tbody><tr><td>Discover</td><td>Comprendre le problème</td><td>Recherche, observation, entretiens, collecte d&#39;informations</td><td>Insights utilisateurs, notes de contexte, liste de problèmes</td></tr><tr><td>Define</td><td>Définir le problème</td><td>Synthèse, focalisation, compromis, reformulation</td><td>Définition du problème, priorités, point d&#39;entrée MVP</td></tr><tr><td>Develop</td><td>Explorer les solutions</td><td>Brainstorming, comparaison, co-création, hypothèses de prototype</td><td>Liste de solutions, schémas de flux, direction de prototype</td></tr><tr><td>Deliver</td><td>Valider les solutions</td><td>Prototypage, tests, itération, livraison</td><td>Prototype, retours de test, version optimisée</td></tr></tbody></table><p>Compressé encore plus, cela donne :</p><ul><li><strong>Discover / Define</strong> : résoudre « faire les bonnes choses »</li><li><strong>Develop / Deliver</strong> : résoudre « faire les choses correctement »</li></ul><h2 id="_6-les-malentendus-les-plus-courants-sur-le-modele-double-diamond" tabindex="-1">6. Les malentendus les plus courants sur le modèle Double Diamond <a class="header-anchor" href="#_6-les-malentendus-les-plus-courants-sur-le-modele-double-diamond" aria-label="Permalink to “6. Les malentendus les plus courants sur le modèle Double Diamond”">​</a></h2><h3 id="_6-1-passer-directement-a-deliver-sans-discover" tabindex="-1">6.1 Passer directement à Deliver sans Discover <a class="header-anchor" href="#_6-1-passer-directement-a-deliver-sans-discover" aria-label="Permalink to “6.1 Passer directement à Deliver sans Discover”">​</a></h3><p>C&#39;est le cas le plus fréquent. Beaucoup de gens, à peine ont-ils une idée, se mettent à dessiner des prototypes, rédiger des PRD, intégrer des modèles, créer des pages.</p><p>Le problème n&#39;est pas que vous ne travaillez pas sérieusement, mais que vous n&#39;avez peut-être même pas confirmé si le problème mérite d&#39;être résolu.</p><h3 id="_6-2-faire-beaucoup-de-discover-mais-jamais-define" tabindex="-1">6.2 Faire beaucoup de Discover, mais jamais Define <a class="header-anchor" href="#_6-2-faire-beaucoup-de-discover-mais-jamais-define" aria-label="Permalink to “6.2 Faire beaucoup de Discover, mais jamais Define”">​</a></h3><p>L&#39;autre extrême est de toujours faire des recherches, lire des documents, interviewer, sans jamais oser converger.</p><p>Le Double Diamond ne vous demande pas de diverger indéfiniment, mais vous rappelle : après la divergence, il faut entrer dans le jugement et les compromis.</p><h3 id="_6-3-apres-define-modifier-subrepticement-le-probleme" tabindex="-1">6.3 Après Define, modifier subrepticement le problème <a class="header-anchor" href="#_6-3-apres-define-modifier-subrepticement-le-probleme" aria-label="Permalink to “6.3 Après Define, modifier subrepticement le problème”">​</a></h3><p>Beaucoup d&#39;équipes, en phase Develop, modifient la définition du problème pour l&#39;adapter à une solution plus facile à réaliser.</p><p>C&#39;est dangereux. Vous n&#39;êtes peut-être plus en train de résoudre le problème, mais en train de trouver des justifications pour la solution que vous préférez.</p><h3 id="_6-4-confondre-deliver-avec-«-mise-en-ligne-complete-»" tabindex="-1">6.4 Confondre Deliver avec « mise en ligne complète » <a class="header-anchor" href="#_6-4-confondre-deliver-avec-«-mise-en-ligne-complete-»" aria-label="Permalink to “6.4 Confondre Deliver avec « mise en ligne complète »”">​</a></h3><p>Deliver ne signifie pas qu&#39;il faut terminer le produit complet. Très souvent, un prototype testable ou un essai utilisateur réel constitue déjà un bon deliver.</p><h2 id="_7-comment-utiliser-le-modele-double-diamond-dans-les-produits-ai" tabindex="-1">7. Comment utiliser le modèle Double Diamond dans les produits AI <a class="header-anchor" href="#_7-comment-utiliser-le-modele-double-diamond-dans-les-produits-ai" aria-label="Permalink to “7. Comment utiliser le modèle Double Diamond dans les produits AI”">​</a></h2><p>Les produits AI tombent particulièrement facilement dans le piège du « capacités d&#39;abord », parce que les capacités des modèles semblent très alléchantes. Vous aurez envie de penser directement :</p><ul><li>Faut-il intégrer le multimodal</li><li>Faut-il faire un Agent</li><li>Faut-il ajouter des workflows</li><li>Faut-il intégrer la voix, l&#39;image, la recherche en ligne</li></ul><p>Mais le modèle Double Diamond vous oblige à demander d&#39;abord :</p><ul><li>Où les utilisateurs sont-ils vraiment bloqués</li><li>Ce blocage nécessite-t-il absolument l&#39;IA</li><li>Sans IA, qu&#39;est-ce qui manque le plus dans les méthodes actuelles</li><li>Une fois l&#39;IA ajoutée, quel est le progrès le plus essentiel</li></ul><p>Cela vous aide à éviter une situation courante : <strong>capacités puissantes, valeur faible.</strong></p><p>Un ordre pratique serait :</p><ol><li>En phase Discover, observer comment les utilisateurs gèrent les tâches actuellement</li><li>En phase Define, écrire le scénario le plus douloureux en une définition de problème claire</li><li>En phase Develop, comparer quelles capacités AI sont les plus adaptées à ce problème</li><li>En phase Deliver, construire une version minimale et la faire tester par de vrais utilisateurs</li></ol><h2 id="_8-un-modele-double-diamond-pret-a-l-emploi" tabindex="-1">8. Un modèle Double Diamond prêt à l&#39;emploi <a class="header-anchor" href="#_8-un-modele-double-diamond-pret-a-l-emploi" aria-label="Permalink to “8. Un modèle Double Diamond prêt à l&#39;emploi”">​</a></h2><p>Si vous êtes en train de créer votre propre produit, vous pouvez suivre cet ordre :</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>Qui sont les utilisateurs que j&#39;ai observés ?</li><li>Quand est la dernière fois qu&#39;ils ont rencontré ce problème ?</li><li>Comment le résolvent-ils actuellement ?</li><li>Où est-ce le plus pénible, le plus lent, le plus angoissant ?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>Parmi tous ces problèmes, lequel mérite le plus d&#39;être résolu en priorité ?</li><li>Quel scénario est le plus fréquent ou le plus crucial ?</li><li>Qui et quoi servirons-nous uniquement dans la première version ?</li><li>Une fois le problème résolu, quel sera le changement d&#39;état de l&#39;utilisateur ?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>Pour ce problème, quelles solutions sont possibles ?</li><li>Quelles sont les plus légères, les plus rapides, les plus faciles à valider ?</li><li>Qu&#39;est-ce qui est indispensable, qu&#39;est-ce qui peut attendre ?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>Que pouvons-nous livrer au minimum pour valider cette direction ?</li><li>Un flux, un prototype, ou un MVP ?</li><li>Qui devons-nous trouver pour tester ?</li><li>Après le test, comment décider : continuer, modifier ou abandonner ?</li></ul><h2 id="_9-un-exemple-comprehensible-meme-par-un-debutant" tabindex="-1">9. Un exemple compréhensible même par un débutant <a class="header-anchor" href="#_9-un-exemple-comprehensible-meme-par-un-debutant" aria-label="Permalink to “9. Un exemple compréhensible même par un débutant”">​</a></h2><p>Supposons que vous voulez créer un outil AI pour « aider les étudiants à préparer leur CV de candidature ».</p><p>Beaucoup de gens entreraient directement dans le deuxième diamant, commençant à penser :</p><ul><li>Faut-il embellir en un clic</li><li>Faut-il faire de la réécriture intelligente</li><li>Faut-il faire correspondre automatiquement avec l&#39;offre d&#39;emploi</li><li>Faut-il générer une lettre de motivation</li></ul><p>Mais selon le modèle Double Diamond, un meilleur processus serait :</p><h3 id="premier-diamant" tabindex="-1">Premier diamant <a class="header-anchor" href="#premier-diamant" aria-label="Permalink to “Premier diamant”">​</a></h3><p><strong>Discover</strong></p><ul><li>Aller parler aux diplômés récents pour savoir quand ils ont modifié leur CV pour la dernière fois</li><li>Voir comment ils transforment l&#39;ancien CV en nouvelle version</li><li>Comprendre s&#39;ils sont surtout gênés par « ne pas savoir écrire », « ne pas savoir modifier », ou « ne pas savoir juger si c&#39;est bien »</li></ul><p><strong>Define</strong></p><ul><li>Converger vers un problème plus spécifique :</li><li>Ce n&#39;est pas « les étudiants ne savent pas faire de CV »</li><li>Mais « les étudiants qui postulent pour la première fois à un stage ont du mal à reformuler leurs expériences existantes en formulations adaptées au poste, ce qui les pousse à retarder leur candidature »</li></ul><h3 id="deuxieme-diamant" tabindex="-1">Deuxième diamant <a class="header-anchor" href="#deuxieme-diamant" aria-label="Permalink to “Deuxième diamant”">​</a></h3><p><strong>Develop</strong></p><ul><li>Imaginer plusieurs solutions : bibliothèque de modèles, réécriture AI, comparaison avec l&#39;offre, notation du CV, exemples de référence</li></ul><p><strong>Deliver</strong></p><ul><li>La première version ne fait que « reformuler les points d&#39;expérience en fonction de la description du poste »</li><li>La faire tester par 5 étudiants, pour voir s&#39;ils soumettent leur première version de CV plus rapidement</li></ul><p>Vous constaterez que, une fois le premier diamant bien fait, le deuxième devient beaucoup plus clair.</p><h2 id="_10-resume" tabindex="-1">10. Résumé <a class="header-anchor" href="#_10-resume" aria-label="Permalink to “10. Résumé”">​</a></h2><p>La force du modèle Double Diamond réside dans le fait qu&#39;il vous aide à décomposer un ensemble chaotique en quatre actions plus claires :</p><ul><li>D&#39;abord, diverger pour comprendre le problème</li><li>Puis, converger pour définir le problème</li><li>Ensuite, diverger pour explorer les solutions</li><li>Enfin, converger pour livrer la solution</li></ul><p>Il ne vous ralentit pas, il vous fait <strong>gagner les détours qui donnent l&#39;impression d&#39;être occupé mais vont dans la mauvaise direction.</strong></p><p>Surtout à l&#39;ère de l&#39;IA, où créer des choses devient de plus en plus rapide, le modèle Double Diamond devient encore plus important. Parce que quand « produire » devient de plus en plus facile, la capacité vraiment rare sera : <strong>êtes-vous en train de résoudre un problème qui mérite d&#39;être résolu, et le faites-vous de la bonne manière.</strong></p><p>Retenez juste cette phrase :</p><p><strong>Faites d&#39;abord les bonnes choses, puis faites les choses correctement.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-comment-utiliser-l-ia-pour-piloter-votre-processus-double-diamond" tabindex="-1"><a href="#top-dd">11. Comment utiliser l&#39;IA pour piloter votre processus Double Diamond</a> <a class="header-anchor" href="#_11-comment-utiliser-l-ia-pour-piloter-votre-processus-double-diamond" aria-label="Permalink to “11. Comment utiliser l&#39;IA pour piloter votre processus Double Diamond”">​</a></h2><p>Le modèle Double Diamond n&#39;est pas un outil AI en soi, mais l&#39;IA est très bien adaptée pour servir d&#39;« accélérateur » dans les quatre phases. L&#39;essentiel n&#39;est pas de laisser l&#39;IA décider à votre place, mais de l&#39;utiliser pour élargir votre vision, organiser les informations, comparer les solutions et générer du matériel de validation.</p><h3 id="_11-1-en-phase-discover-utilisez-l-ia-pour-preparer-le-terrain" tabindex="-1">11.1 En phase Discover, utilisez l&#39;IA pour préparer le terrain <a class="header-anchor" href="#_11-1-en-phase-discover-utilisez-l-ia-pour-preparer-le-terrain" aria-label="Permalink to “11.1 En phase Discover, utilisez l&#39;IA pour préparer le terrain”">​</a></h3><p>Avant les entretiens et la recherche formels, vous pouvez demander à l&#39;IA de faire un balayage léger des problèmes, comme :</p><ul><li>Quelles alternatives existent sur le marché</li><li>De quoi les utilisateurs se plaignent-ils le plus dans les communautés publiques</li><li>Dans quels contextes et pour quels publics ce problème est-il courant</li><li>Que les produits existants négligent-ils souvent</li></ul><p>Cette étape ne remplace pas la recherche terrain, mais elle est idéale pour construire rapidement une carte des problèmes.</p><p>Une entrée très simple pour un débutant pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Je veux créer un outil pour aider les étudiants à modifier leur CV.</span></span>
<span class="line"><span>Ne me proposez pas de fonctionnalités, aidez-moi d&#39;abord à voir quels problèmes les gens rencontrent le plus souvent.</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Carte préliminaire des problèmes :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Ne sait pas quelles expériences mentionner</span></span>
<span class="line"><span>2. Ne sait pas comment adapter le CV pour chaque poste</span></span>
<span class="line"><span>3. Après de nombreuses modifications, on n&#39;est toujours pas sûr que c&#39;est bien</span></span>
<span class="line"><span>4. On a besoin de quelqu&#39;un pour relire, mais on ne veut pas déranger</span></span>
<span class="line"><span>5. Parce qu&#39;on n&#39;est pas sûr, on retarde l&#39;envoi</span></span></code></pre></div><p>Ce type de résultat ne remplace pas vos conclusions, mais vous permet d&#39;entrer plus vite dans le Discover.</p><h3 id="_11-2-en-phase-define-laissez-l-ia-vous-aider-a-converger-vers-une-definition-du-probleme" tabindex="-1">11.2 En phase Define, laissez l&#39;IA vous aider à converger vers une définition du problème <a class="header-anchor" href="#_11-2-en-phase-define-laissez-l-ia-vous-aider-a-converger-vers-une-definition-du-probleme" aria-label="Permalink to “11.2 En phase Define, laissez l&#39;IA vous aider à converger vers une définition du problème”">​</a></h3><p>Beaucoup de gens, après avoir collecté beaucoup de matériel, trouvent la partie la plus difficile de condenser le problème en une phrase vraiment claire. Vous pouvez confier vos notes de recherche à l&#39;IA et lui demander de les compresser en plusieurs définitions candidates :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Voici les retours utilisateurs et les notes de recherche que j&#39;ai collectés en phase Discover :</span></span>
<span class="line"><span>[insérez le contenu]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Merci de m&#39;aider à faire trois choses :</span></span>
<span class="line"><span>1. Identifier les modèles de problèmes les plus fréquents</span></span>
<span class="line"><span>2. Classer 3 problèmes prioritaires par fréquence, intensité de douleur et validabilité</span></span>
<span class="line"><span>3. Écrire chaque problème en une définition spécifique</span></span></code></pre></div><p>Vous pouvez même écrire une entrée très simple :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Les problèmes que j&#39;ai collectés sont :</span></span>
<span class="line"><span>1. Les gens ne savent pas quoi mettre dans leur CV</span></span>
<span class="line"><span>2. Les gens ne savent pas comment le modifier</span></span>
<span class="line"><span>3. Les gens trouvent toujours que ce n&#39;est pas assez bien et n&#39;osent pas l&#39;envoyer</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Lequel est le plus adapté pour une première version ?</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Problème recommandé en priorité :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>« Les étudiants qui postulent pour la première fois à un stage ne sont pas sûrs que leur CV est au niveau requis pour être envoyé, ce qui les pousse à modifier sans cesse et à retarder leur candidature. »</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Raisons :</span></span>
<span class="line"><span>1. Ce problème est plus spécifique</span></span>
<span class="line"><span>2. Il explique le comportement de procrastination</span></span>
<span class="line"><span>3. Il est plus facile de concevoir une petite version pour le valider</span></span></code></pre></div><p>Ce type de résultat est utile parce qu&#39;il vous aide à passer d&#39;un ensemble de problèmes flous à une définition plus proche d&#39;un point de départ MVP.</p><h3 id="_11-3-en-phase-develop-utilisez-l-ia-pour-diverger-sur-plusieurs-solutions" tabindex="-1">11.3 En phase Develop, utilisez l&#39;IA pour diverger sur plusieurs solutions <a class="header-anchor" href="#_11-3-en-phase-develop-utilisez-l-ia-pour-diverger-sur-plusieurs-solutions" aria-label="Permalink to “11.3 En phase Develop, utilisez l&#39;IA pour diverger sur plusieurs solutions”">​</a></h3><p>Beaucoup de gens, une fois le problème défini, ne se concentrent que sur la première solution qui leur vient à l&#39;esprit. L&#39;IA est idéale ici pour vous forcer à diverger :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>J&#39;ai défini un problème central : [votre définition du problème]</span></span>
<span class="line"><span>Ne me donnez pas une seule réponse finale, mais proposez 2-3 directions de solution pour chacun des angles suivants :</span></span>
<span class="line"><span>1. Le MVP le plus léger</span></span>
<span class="line"><span>2. La solution la plus adaptée pour valider le besoin</span></span>
<span class="line"><span>3. La solution la plus adaptée pour améliorer l&#39;expérience</span></span>
<span class="line"><span>4. Une solution sans IA</span></span>
<span class="line"><span>5. Une solution avec IA</span></span>
<span class="line"><span>Enfin, comparez les avantages, les risques et les coûts de validation de chaque solution.</span></span></code></pre></div><p>Ainsi, vous ne vous enfermerez pas trop tôt dans une seule solution.</p><p>Une entrée simple pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ma définition du problème est :</span></span>
<span class="line"><span>« Les étudiants ne sont pas sûrs que leur CV est prêt à être envoyé, donc ils retardent. »</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Proposez-moi 4 solutions différentes, pas une seule.</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Solution 1 : Checklist de validation du CV</span></span>
<span class="line"><span>Solution 2 : Réécriture ciblée en fonction de la description du poste</span></span>
<span class="line"><span>Solution 3 : Upload du CV avec indicateurs de risque</span></span>
<span class="line"><span>Solution 4 : Comparaison avec des exemples de qualité pour aider à évaluer l&#39;écart</span></span></code></pre></div><p>Vous êtes alors plus en mesure d&#39;entrer dans la « comparaison de solutions » au lieu de ne vous concentrer que sur la réécriture AI.</p><h3 id="_11-4-en-phase-deliver-utilisez-l-ia-pour-generer-des-textes-de-prototype-et-du-materiel-de-test" tabindex="-1">11.4 En phase Deliver, utilisez l&#39;IA pour générer des textes de prototype et du matériel de test <a class="header-anchor" href="#_11-4-en-phase-deliver-utilisez-l-ia-pour-generer-des-textes-de-prototype-et-du-materiel-de-test" aria-label="Permalink to “11.4 En phase Deliver, utilisez l&#39;IA pour générer des textes de prototype et du matériel de test”">​</a></h3><p>Quand vous entrez en phase Deliver, l&#39;IA est très adaptée pour accélérer ces tâches :</p><ul><li>Générer les textes de pages pour un prototype basse fidélité</li><li>Organiser un script de test utilisateur</li><li>Générer plusieurs versions comparables de titres, boutons, descriptions</li><li>Synthétiser les retours post-test en liste de problèmes</li></ul><p>Par exemple, vous pouvez demander à l&#39;IA de générer un script de test utilisateur de 20 minutes, ou de classer les retours de 5 utilisateurs en « continuer / changer de direction / mettre en pause ».</p><p>Une entrée minimale pourrait être :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>J&#39;ai fait un prototype très simple :</span></span>
<span class="line"><span>l&#39;utilisateur uploade son CV, le système lui indique quels éléments ne sont pas encore prêts pour l&#39;envoi.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Générez-moi un script de test utilisateur de 15 minutes.</span></span></code></pre></div><p>L&#39;IA pourrait répondre :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Script de test de 15 minutes :</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. D&#39;abord, demandez à l&#39;utilisateur de décrire sa dernière expérience de candidature</span></span>
<span class="line"><span>2. Laissez l&#39;utilisateur uploader son CV de manière autonome</span></span>
<span class="line"><span>3. Observez s&#39;il comprend les résultats du retour</span></span>
<span class="line"><span>4. Demandez : parmi ces indications, lesquelles sont les plus utiles, lesquelles sont confuses</span></span>
<span class="line"><span>5. Demandez : avant la prochaine candidature, aimeriez-vous réutiliser cet outil</span></span></code></pre></div><p>Ce type de résultat est pratique parce qu&#39;il vous fait passer de « j&#39;ai fini mon prototype » à « comment je le teste ensuite ».</p><h3 id="_11-5-laissez-l-ia-jouer-le-role-de-«-gardien-des-phases-»" tabindex="-1">11.5 Laissez l&#39;IA jouer le rôle de « gardien des phases » <a class="header-anchor" href="#_11-5-laissez-l-ia-jouer-le-role-de-«-gardien-des-phases-»" aria-label="Permalink to “11.5 Laissez l&#39;IA jouer le rôle de « gardien des phases »”">​</a></h3><p>Le problème le plus courant du modèle Double Diamond est que les gens sautent les étapes. Vous pouvez demander à l&#39;IA de jouer un gardien, pour vous rappeler où vous êtes vraiment :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Merci de jouer le rôle de coach en processus produit.</span></span>
<span class="line"><span>Voici l&#39;état actuel de mon projet : [votre description]</span></span>
<span class="line"><span>Déterminez si je suis plutôt en Discover, Define, Develop ou Deliver.</span></span>
<span class="line"><span>Et dites-moi :</span></span>
<span class="line"><span>1. Est-ce que j&#39;ai sauté une étape trop tôt</span></span>
<span class="line"><span>2. Quelle est l&#39;action la plus importante à compléter à l&#39;étape actuelle</span></span>
<span class="line"><span>3. Quelles choses je ne dois pas faire pour l&#39;instant</span></span></code></pre></div><p>C&#39;est particulièrement utile pour les débutants, car il est facile de « commencer à dessiner des prototypes avant d&#39;avoir clarifié le problème ».</p><h2 id="📚-exercices" tabindex="-1">📚 Exercices <a class="header-anchor" href="#📚-exercices" aria-label="Permalink to “📚 Exercices”">​</a></h2><p>En vous basant sur le contenu ci-dessus, veuillez réaliser les exercices suivants :</p><ol><li>Choisissez une idée produit que vous avez récemment, et rédigez le brouillon des quatre étapes Discover, Define, Develop, Deliver</li><li>En phase Define, forcez-vous à réduire le problème à une phrase spécifique</li><li>En phase Develop, listez au moins 3 solutions différentes, au lieu de ne vous concentrer que sur la première idée venue</li><li>En phase Deliver, écrivez une version minimale validable livrable en une semaine</li></ol><h2 id="lectures-complementaires" tabindex="-1">Lectures complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to “Lectures complémentaires”">​</a></h2><p>Cet article s&#39;inspire principalement des ressources officielles du Design Council sur le Double Diamond, idéales pour approfondir :</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council : The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council : Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council : History of the Double Diamond</a></li></ul>`,170))])}}});export{b as __pageData,v as default};
